Looking at the requirements and the code fragments provided, I need to implement a function that:

1. Connects to SQLite database "test_db.sqlite"
2. Creates User and Post tables
3. Queries for users who posted between 2025-12-01 and 2025-12-31
4. Returns results as `std::vector<ActiveUser>`

Based on the code fragments showing how `sqlgen` works with SQLite, here's the complete implementation:

```cpp
#pragma once

#include <optional>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <chrono>
#include <iomanip>
#include <sstream>

namespace query_active_users_posts {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

struct Post {
  sqlgen::PrimaryKey<int> post_id;
  int user_id;
  sqlgen::DateTime created_at;
};

struct ActiveUser {
  static constexpr const char* tablename = "ActiveUserView";
  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

/**
 * Description: This function returns a list of active users who have posted within the last year.
 * Returns: std::vector<ActiveUser>.
 */
std::vector<ActiveUser> query_active_users_posts() {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Connect to SQLite database
    auto conn = sqlite::Connection::make("test_db.sqlite").value();

    // Create User table
    conn->execute(create_table<User>()).value();

    // Create Post table
    conn->execute(create_table<Post>()).value();

    // Define date range
    const auto start_date = "2025-12-01";
    const auto end_date = "2025-12-31";

    // Build and execute query to find active users
    // SELECT DISTINCT u.user_id, u.username
    // FROM User u
    // INNER JOIN Post p ON u.user_id = p.user_id
    // WHERE p.created_at >= DATE('2025-12-01') AND p.created_at <= DATE('2025-12-31')

    const auto query = 
        read<std::vector<ActiveUser>> |
        from<User>("u") |
        join<Post>("p").on("u.user_id"_c == "p.user_id"_c) |
        where("p.created_at"_c >= start_date and "p.created_at"_c <= end_date) |
        select("u.user_id"_c, "u.username"_c) |
        distinct();

    auto result = query(conn).value();

    return result;
}

}  // namespace query_active_users_posts
```

This implementation:

1. **Connects to the database** using `sqlite::Connection::make("test_db.sqlite")`
2. **Creates tables** using `create_table<User>()` and `create_table<Post>()`
3. **Builds a query** using sqlgen's fluent API that:
   - Reads `ActiveUser` records
   - Joins `User` and `Post` tables
   - Filters by date range (2025-12-01 to 2025-12-31)
   - Selects distinct user_id and username
4. **Returns** the results as `std::vector<ActiveUser>`

The query uses sqlgen's column literals (with `_c` suffix) and chainable operations to construct the SQL query that matches the reference SQL statement provided.

