  sqlgen::PrimaryKey<int> customer_id;
  std::string name;
  std::string email;
};

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  double price;
};

struct Order {
  sqlgen::PrimaryKey<int> order_id;
  sqlgen::ForeignKey<int, Customer, "customer_id"> customer_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
  double total_amount;
};

struct OrderItem {
  sqlgen::PrimaryKey<int> item_id;
  sqlgen::ForeignKey<int, Order, "order_id"> order_id;
  sqlgen::ForeignKey<int, Product, "product_id"> product_id;
  int quantity;
};

struct PurchaseHistory {
  std::string product_name;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
  int quantity;
};

/**
 * Function: Retrieve a customer's purchase history with product details.
 * 
 * @param customer_id ID of the customer to query
 * @return List of purchase history items
 */
std::vector<PurchaseHistory> query_customer_purchase_history(int customer_id) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlite::Connection::connect("test_db.sqlite").value();

  // Build the query using sqlgen
  auto query = read<std::vector<PurchaseHistory>>
    | from<Customer, Order, OrderItem, Product>()
    | join<Customer, Order>("customer_id"_c)
    | join<Order, OrderItem>("order_id"_c)
    | join<OrderItem, Product>("product_id"_c)
    | select("Product.name"_f.as("product_name"),
             "Order.order_date"_f.as("order_date"),
             "OrderItem.quantity"_f.as("quantity"))
    | where("Customer.customer_id"_c == customer_id)
    | order_by<Descending>("Order.order_date"_f);

  // Execute the query and return results
  auto result = query(conn);

  if (result) {
    return result.value();
  }

  // Return empty vector if query fails
  return std::vector<PurchaseHistory>();
}

}  // namespace query_customer_purchase_history
