Looking at the code fragments and requirements, I need to complete the function that:
1. Connects to SQLite database
2. Joins Product and Sale tables
3. Aggregates sales data by category
4. Filters categories with total sales > 5000
5. Returns results as CategoryReport records

Here's the complete file:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace query_product_sales_report {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string category;
};

struct Sale {
  sqlgen::PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  double amount;
};

struct CategoryReport {
  std::string category;
  int total_qty;
  double total_amt;
};

/**
 * Function: Generate a sales report by product category.
 * @return vector<CategoryReport>
 */
std::vector<CategoryReport> query_product_sales_report() {
    // Connect to SQLite database
    auto conn = sqlgen::sqlite::Connection::connect("test_db.sqlite");

    if (!conn) {
        // Return empty vector if connection fails
        return std::vector<CategoryReport>();
    }

    // Define table aliases
    auto p = sqlgen::Ref<Product>::from("Product").as("p");
    auto s = sqlgen::Ref<Sale>::from("Sale").as("s");

    // Build the query using sqlgen API
    auto query = sqlgen::select_from(p)
        .inner_join(s).on(sqlgen::col(p, &Product::product_id) == 
                         sqlgen::col(s, &Sale::product_id))
        .select(
            sqlgen::as<"category">(sqlgen::col(p, &Product::category)),
            sqlgen::as<"total_qty">(sqlgen::sum(sqlgen::col(s, &Sale::quantity))),
            sqlgen::as<"total_amt">(sqlgen::sum(sqlgen::col(s, &Sale::amount)))
        )
        .group_by(sqlgen::col(p, &Product::category))
        .having(sqlgen::sum(sqlgen::col(s, &Sale::amount)) > 5000.0);

    // Execute query and collect results
    auto result = sqlgen::read<CategoryReport>(*conn, query);

    if (!result) {
        // Return empty vector if query fails
        return std::vector<CategoryReport>();
    }

    // Convert result to vector
    std::vector<CategoryReport> reports;
    for (const auto& report : *result) {
        reports.push_back(report);
    }

    return reports;
}

}  // namespace query_product_sales_report
```

