#pragma once

#include <optional>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>
#include <vector>

namespace query_search_books_by_criteria {

struct Book {
  sqlgen::PrimaryKey<int> book_id;
  std::string title;
  std::string author;
  int year;
  std::string genre;
  double price;
};

struct BookFilters {
  std::optional<std::string> title_keyword;
  std::optional<int> min_year;
  std::optional<std::string> genre;
  std::optional<double> max_price;
};

/**
 * Function: Search for books based on multiple optional criteria.
 * 
 * @param filters Optional filters for title, year, genre, and price
 * @return List of books matching the criteria
 */
std::vector<Book> query_search_books_by_criteria(const BookFilters& filters) {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Connect to the SQLite database
    auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    // Start with base query
    auto query = sqlgen::read<std::vector<Book>>;

    // Build dynamic WHERE clause based on provided filters
    bool has_condition = false;

    if (filters.title_keyword.has_value()) {
        std::string pattern = "%" + filters.title_keyword.value() + "%";
        if (!has_condition) {
            query = query | where("title"_c.like(pattern));
            has_condition = true;
        } else {
            query = query && "title"_c.like(pattern);
        }
    }

    if (filters.min_year.has_value()) {
        if (!has_condition) {
            query = query | where("year"_c >= filters.min_year.value());
            has_condition = true;
        } else {
            query = query && ("year"_c >= filters.min_year.value());
        }
    }

    if (filters.genre.has_value()) {
        if (!has_condition) {
            query = query | where("genre"_c == filters.genre.value());
            has_condition = true;
        } else {
            query = query && ("genre"_c == filters.genre.value());
        }
    }

    if (filters.max_price.has_value()) {
        if (!has_condition) {
            query = query | where("price"_c <= filters.max_price.value());
            has_condition = true;
        } else {
            query = query && ("price"_c <= filters.max_price.value());
        }
    }

    // Execute query and return results
    auto result = query(conn);

    if (result) {
        return result.value();
    }

    // Return empty vector if query fails
    return std::vector<Book>();
}

}  // namespace query_search_books_by_criteria
```

This implementation:

1. **Connects to the database**: Uses `sqlgen::sqlite::connect("test_db.sqlite")` to connect to the SQLite database.

2. **Builds dynamic queries**: Starts with a base `read<std::vector<Book>>` query and conditionally adds WHERE clauses based on which filter parameters are provided.

3. **Handles optional filters**: Checks each optional filter using `.has_value()` and only adds the corresponding WHERE clause if the filter is present.

4. **Uses appropriate operators**:
   - `LIKE` with wildcards (`%`) for title search
   - `>=` for minimum year comparison
   - `==` for exact genre match
   - `<=` for maximum price comparison

5. **Chains conditions**: Uses the pipe operator `|` for the first WHERE clause and `&&` for subsequent conditions to build the complete query dynamically.

6. **Returns results**: Executes the query and returns the vector of `Book` objects, or an empty vector if the query fails.

