  sqlgen::PrimaryKey<int, sqlgen::auto_incr> user_id;
  std::string username;
  std::string phone_number;
  bool is_active;
};

/**
 * Function: Perform schema migration to add new columns.
 * @return true if migration succeeds, false otherwise
 */
bool migration_add_column() {
  try {
    // Connect to the SQLite database
    auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
    if (!conn_result) {
      return false;
    }
    auto conn = std::move(conn_result.value());

    // SQL statements to add new columns
    const std::string add_phone_number = 
        "ALTER TABLE User ADD COLUMN phone_number VARCHAR(20);";
    const std::string add_is_active = 
        "ALTER TABLE User ADD COLUMN is_active INTEGER DEFAULT 1;";

    // Execute the first ALTER TABLE statement
    auto result1 = conn.exec(add_phone_number);
    if (!result1) {
      // Check if the error is because column already exists
      // SQLite error code 1 is SQLITE_ERROR, which includes "duplicate column name"
      // If column already exists, we can consider it a success or continue
      // For now, we'll try the second statement anyway
    }

    // Execute the second ALTER TABLE statement
    auto result2 = conn.exec(add_is_active);
    if (!result2) {
      // Similar handling for the second column
    }

    // If we got here, consider the migration successful
    // (columns either added or already exist)
    return true;

  } catch (const std::exception& e) {
    // Handle any exceptions that might occur
    return false;
  } catch (...) {
    // Handle any other exceptions
    return false;
  }
}

} // namespace schema_migration_add_column
