Looking at the code fragments and the requirements, I need to implement a `soft_delete_records` function that:
1. Connects to SQLite database "test_db.sqlite"
2. Updates records with given doc_ids to set `is_deleted = 1` and `deleted_at = CURRENT_TIMESTAMP`
3. Uses a transaction for batch updates

Based on the sqlgen library patterns shown in the fragments, here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace soft_delete_records {

struct Document {
  sqlgen::PrimaryKey<int> doc_id;
  std::string title;
  int is_deleted = 0;
  std::optional<sqlgen::DateTime> deleted_at;
};

bool soft_delete_records(const std::vector<int>& ids) {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    if (ids.empty()) {
        return true;
    }

    // Connect to the SQLite database
    auto conn_result = sqlite::connect("test_db.sqlite");
    if (!conn_result) {
        return false;
    }

    auto& conn = conn_result.value();

    // Begin transaction
    auto begin_result = conn.execute("BEGIN TRANSACTION;");
    if (!begin_result) {
        return false;
    }

    // Update each document in the transaction
    bool success = true;
    for (const auto& id : ids) {
        // Create an update query for each document
        auto update_result = conn.execute(
            update<Document> | 
            set("is_deleted"_c = 1, "deleted_at"_c = sqlgen::DateTime::now()) |
            where("doc_id"_c == id)
        );

        if (!update_result) {
            success = false;
            break;
        }
    }

    // Commit or rollback based on success
    if (success) {
        auto commit_result = conn.execute("COMMIT;");
        return commit_result.has_value();
    } else {
        conn.execute("ROLLBACK;");
        return false;
    }
}

}  // namespace soft_delete_records
```

This implementation:
1. Connects to the "test_db.sqlite" database using `sqlite::connect()`
2. Starts a transaction with `BEGIN TRANSACTION`
3. Iterates through each `doc_id` and updates the corresponding record using sqlgen's `update` DSL with `set()` and `where()` clauses
4. Sets `is_deleted` to 1 and `deleted_at` to the current timestamp
5. Commits the transaction if all updates succeed, or rolls back if any fail
6. Returns `true` on success, `false` on failure

The function handles edge cases like an empty ID list and properly manages the transaction to ensure atomicity of the batch update operation.

