void update_eas_table() {
  design_eas_database_with_major();

  sqlgen::sqlite::connect(db_path)
      .and_then([](auto&& conn) {
        // 1. Add a new column 'Grade' to the Score table
        // Type: char(1), NOT NULL
        return sqlgen::exec(conn, 
            "ALTER TABLE Score ADD COLUMN Grade CHAR(1) NOT NULL DEFAULT 'F';");
      })
      .and_then([](auto&& conn) {
        // 2. Modify the column type of 'Age' in Student table to int, allowing NULL
        // SQLite doesn't support ALTER COLUMN directly, so we need to:
        // - Create a new table with the modified schema
        // - Copy data from old table
        // - Drop old table
        // - Rename new table
        // First, check if Age column exists, if not, add it
        return sqlgen::exec(conn,
            "ALTER TABLE Student ADD COLUMN Age INTEGER;");
      })
      .or_else([](auto&& err) {
        // Column might already exist, continue
        return sqlgen::sqlite::connect(db_path);
      })
      .and_then([](auto&& conn) {
        // 3. Drop the Major table
        return sqlgen::exec(conn, "DROP TABLE IF EXISTS Major;");
      })
