Looking at the code fragments and requirements, I need to implement the `upsert_user_profile` function that:
1. Connects to SQLite database "test_db.sqlite"
2. Uses `INSERT OR REPLACE` to upsert the user profile
3. Returns true on success, false on failure

Based on the code fragments, I can see that:
- `sqlgen::sqlite::connect()` is used to connect to SQLite databases
- The library supports SQL generation and execution
- I need to use the `INSERT OR REPLACE` syntax for SQLite

Here's the complete file:

```cpp
#pragma once

#include <optional>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>

namespace upsert_user_profile {

struct UserProfile {
  sqlgen::PrimaryKey<int> user_id;
  std::optional<std::string> bio;
  std::optional<std::string> avatar_url;
};

/**
 * @brief Insert or update a user profile in the database.
 *
 * @param u The user profile to insert or update.
 * @return true If the operation is successful.
 * @return false If the operation fails.
 */
bool upsert_user_profile(const UserProfile& u) {
  try {
    // Connect to the SQLite database
    auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    // Prepare the INSERT OR REPLACE statement
    const std::string sql = 
        "INSERT OR REPLACE INTO UserProfile (user_id, bio, avatar_url) VALUES (?, ?, ?);";

    // Execute the statement with the user profile data
    auto result = conn.exec(sql, u.user_id.value(), u.bio, u.avatar_url);

    // Check if the operation was successful
    if (result) {
      return true;
    }

    return false;
  } catch (...) {
    // If any exception occurs, return false
    return false;
  }
}

} // namespace upsert_user_profile
```

