Based on the code fragments and the requirements, here's the complete implementation:

```cpp
#pragma once

#include <ranges>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace schema_create_view_sales_summary {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  double price;
  int stock;
};

struct Sale {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> sale_id;
  int product_id;
  int quantity;
  double amount;
};

struct SalesSummary {
  static constexpr bool is_view = true;
  std::string product_name;
  int total_quantity;
  double total_revenue;
};

/**
 * Function: Create a view SalesSummary that aggregates sales by product.
 * @return A vector of SalesSummary structs
 */
std::vector<SalesSummary> create_view_sales_summary() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  const auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Create tables if they don't exist
  conn.create_table<Product>();
  conn.create_table<Sale>();

  // Create the view using CREATE VIEW AS with JOIN and aggregation
  conn.create_view_as<SalesSummary>(
      select_as<SalesSummary>(
          "p"_col / "name"_col,
          sum("s"_col / "quantity"_col),
          sum("s"_col / "amount"_col))
          .from<Sale>("s")
          .join<Product>("p")
          .on("s"_col / "product_id"_col == "p"_col / "product_id"_col)
          .group_by("p"_col / "name"_col));

  // Query and return the view data
  const auto results = conn.select<SalesSummary>().from<SalesSummary>().run();

  return results;
}

}  // namespace schema_create_view_sales_summary
```

This implementation:

1. **Connects to the SQLite database** "test_db.sqlite" using `sqlgen::sqlite::connect()`
2. **Creates the necessary tables** (Product and Sale) if they don't exist
3. **Creates the SalesSummary view** using `create_view_as()` with:
   - A JOIN between Sale and Product tables
   - Aggregation functions (SUM) for quantity and amount
   - GROUP BY on product name
4. **Queries the view** and returns the results as a vector of `SalesSummary` structs

The view aggregates sales data by product, showing product name, total quantity sold, and total revenue, exactly as specified in the reference SQL statement.

