```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace right_join_departments_projects {

struct Department {
  sqlgen::PrimaryKey<int> department_id;
  std::string name;
};

struct Project {
  sqlgen::PrimaryKey<int> project_id;
  int department_id;
  std::string name;
};

struct DepProj {
  std::string department_name;
  std::optional<std::string> project_name;
};

/**
 * This function demonstrates how to perform a right join between departments and projects using sqlgen read API.
 * Returns: std::vector<DepProj>, where each struct contains the department name (if available) and the project name.
 */
std::vector<DepProj> right_join_departments_projects() {
  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::Connection::connect("test_db.sqlite").value();

  // Perform RIGHT JOIN: Department RIGHT JOIN Project
  // This ensures all departments are included, even if they have no projects
  auto results = conn.read<Department>()
                     .right_join<Project>(
                         [](const auto& dept, const auto& proj) {
                           return dept.department_id == proj.department_id;
                         })
                     .collect()
                     .value();

  // Transform the results into DepProj structs
  std::vector<DepProj> dep_proj_list;
  dep_proj_list.reserve(results.size());

  for (const auto& [dept, proj] : results) {
    DepProj dp;
    dp.department_name = dept.name;
    dp.project_name = proj ? std::optional<std::string>(proj->name) : std::nullopt;
    dep_proj_list.push_back(std::move(dp));
  }

  return dep_proj_list;
}

}  // namespace right_join_departments_projects
```

