Looking at the code structure and the requirements, I need to implement a function that:
1. Connects to SQLite database "test_db.sqlite"
2. Performs an INNER JOIN between User and Friendship tables
3. Returns a vector of FriendConnection structs with the names of friends

Based on the code fragments and the sqlgen library patterns, here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace analyze_social_network {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

struct Friendship {
  int user1_id;
  int user2_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> created_at;
};

struct FriendConnection {
  std::string user1_name;
  std::string user2_name;
};

/**
 * Analyze who and whom are friends in the social network.
 * Returns: std::vector<FriendConnection>.
 */
std::vector<FriendConnection> analyze_social_network_impl() {
    // Connect to the SQLite database
    auto conn = sqlgen::sqlite::Connection("test_db.sqlite");

    // Create the SQL query using INNER JOIN
    // We need to join Friendship with User twice to get both usernames
    auto query = sqlgen::select(
        sqlgen::as<"user1_name">(sqlgen::col<"u1", &User::username>()),
        sqlgen::as<"user2_name">(sqlgen::col<"u2", &User::username>())
    )
    .from<"f">(sqlgen::table<"Friendship">())
    .inner_join<"u1">(
        sqlgen::table<"User">(),
        sqlgen::col<"f", &Friendship::user1_id>() == sqlgen::col<"u1", &User::user_id>()
    )
    .inner_join<"u2">(
        sqlgen::table<"User">(),
        sqlgen::col<"f", &Friendship::user2_id>() == sqlgen::col<"u2", &User::user_id>()
    );

    // Execute the query and collect results
    auto result = conn.select(query).collect<std::vector<FriendConnection>>();

    // Handle the result
    if (result) {
        return std::move(*result);
    } else {
        // Return empty vector if query fails
        return std::vector<FriendConnection>();
    }
}

}  // namespace analyze_social_network
```

This implementation:

1. **Creates a connection** to "test_db.sqlite" using `sqlgen::sqlite::Connection`
2. **Builds the query** using sqlgen's query builder API:
   - Selects usernames from both users in the friendship
   - Uses aliases "u1" and "u2" for the two User table joins
   - Performs INNER JOINs to match user_id1 and user_id2 with the User table
3. **Executes the query** using `conn.select()` and collects results into a vector of `FriendConnection` structs
4. **Returns the results** or an empty vector if the query fails

The query effectively translates to:
```sql
SELECT u1.username AS user1_name, u2.username AS user2_name
FROM Friendship f
INNER JOIN User u1 ON f.user1_id = u1.user_id
INNER JOIN User u2 ON f.user2_id = u2.user_id
```

