namespace mathematical_operations_analysis {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  double price;
  int quantity;
  double discount_rate;
};

struct MathAnalysis {
  int product_id;
  std::string name;
  double abs_price;
  double ceil_price;
  double floor_price;
  double rounded_price;
  double exp_discount;
  double ln_price;
  double log2_quantity;
  double sin_discount;
  double cos_discount;
  double tan_discount;
  double sqrt_quantity;
};

/**
 * Insert products into a temporary SQLite table and run a SELECT that computes
 * various mathematical expressions, returning results as std::vector<MathAnalysis>.
 */
std::vector<MathAnalysis> analyze_mathematical_operations() {
  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Build the SELECT query with mathematical operations
  auto query = sqlgen::select_from<Product>(
    sqlgen::col<&Product::product_id>(),
    sqlgen::col<&Product::name>(),
    sqlgen::as<"abs_price">(sqlgen::abs(sqlgen::col<&Product::price>())),
    sqlgen::as<"ceil_price">(sqlgen::ceil(sqlgen::col<&Product::price>())),
    sqlgen::as<"floor_price">(sqlgen::floor(sqlgen::col<&Product::price>())),
    sqlgen::as<"rounded_price">(sqlgen::round(sqlgen::col<&Product::price>(), 2)),
    sqlgen::as<"exp_discount">(sqlgen::exp(sqlgen::col<&Product::discount_rate>() / 100.0)),
    sqlgen::as<"ln_price">(sqlgen::ln(sqlgen::col<&Product::price>())),
    sqlgen::as<"log2_quantity">(sqlgen::log2(sqlgen::col<&Product::quantity>())),
    sqlgen::as<"sin_discount">(sqlgen::sin(sqlgen::col<&Product::discount_rate>())),
    sqlgen::as<"cos_discount">(sqlgen::cos(sqlgen::col<&Product::discount_rate>())),
    sqlgen::as<"tan_discount">(sqlgen::tan(sqlgen::col<&Product::discount_rate>())),
    sqlgen::as<"sqrt_quantity">(sqlgen::sqrt(sqlgen::col<&Product::quantity>()))
  );

  // Execute the query and collect results
  auto result = conn.read<MathAnalysis>(query);

  if (!result) {
    return {};
  }

  return *result;
}

}  // namespace mathematical_operations_analysis

