  double tax_rate;
  double gross_total;
  double discounted_total;
  double final_total;
  double unit_cost;
  int quantity_group;
  double estimated_profit;
};

/**
 * Calculate per-item order metrics by querying the OrderItem table
 * and evaluating SQL expressions for totals, discounts, taxes, cost, grouping, and estimated profit.
 * @param items Vector of OrderItem records to analyze.
 * @return std::vector<OrderMetrics> Analysis results for each order item.
 */
std::vector<OrderMetrics> calculate_order_metrics_impl() {
  using namespace sqlgen;

  // Connect to SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  if (!conn) {
    return {};
  }

  // Build the query with arithmetic operations
  auto query = select_from<OrderItem>(
    "item_id"_c,
    "order_id"_c,
    "product_id"_c,
    "unit_price"_c,
    "quantity"_c,
    coalesce("discount_rate"_c, 0.0).as<"discount_rate">(),
    coalesce("tax_rate"_c, 0.0).as<"tax_rate">(),
    // Calculate gross total: unit_price * quantity
    ("unit_price"_c * "quantity"_c).as<"gross_total">(),
    // Calculate discounted total: unit_price * quantity * (1 - discount_rate/100)
    ("unit_price"_c * "quantity"_c * (1.0 - coalesce("discount_rate"_c, 0.0) / 100.0)).as<"discounted_total">(),
    // Calculate final total with tax: discounted_total * (1 + tax_rate/100)
    ("unit_price"_c * "quantity"_c * (1.0 - coalesce("discount_rate"_c, 0.0) / 100.0) * 
     (1.0 + coalesce("tax_rate"_c, 0.0) / 100.0)).as<"final_total">(),
    // Calculate unit cost: total / quantity (simplified to unit_price)
    ("unit_price"_c * "quantity"_c / "quantity"_c).as<"unit_cost">(),
    // Calculate quantity group using modulo
    ("quantity"_c % 10).as<"quantity_group">(),
    // Calculate estimated profit
    ("unit_price"_c * 0.3).as<"estimated_profit">()
  ) | to<OrderMetrics>;

  // Execute query and return results
  auto result = conn.and_then(query);

  if (result) {
    return result.value();
  }

  return {};
}

}  // namespace calculate_order_metrics
```

