Looking at the code fragments and the requirements, I need to implement a function that demonstrates cascade deletion in SQLite. Based on the test examples, I can see how to use the `sqlgen` library with SQLite.

Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace cascade_delete_demo {

struct Parent {
  sqlgen::PrimaryKey<int> parent_id;
  std::string name;
};

struct Child {
  sqlgen::PrimaryKey<int> child_id;
  sqlgen::ForeignKey<int, Parent, "parent_id"> parent_id;
  std::string note;
};

/**
 * Demonstrates cascade delete behavior in SQLite using foreign key constraints.
 * @param parent_id The ID of the parent record to delete.
 * Returns: true if the cascade delete worked as expected, false otherwise.
 */
bool cascade_delete_demo(int parent_id) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn_result = sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return false;
  }

  // Enable foreign key constraints (required for SQLite)
  auto conn = std::move(conn_result.value());
  auto enable_fk = conn.execute("PRAGMA foreign_keys = ON;");
  if (!enable_fk) {
    return false;
  }

  // Drop existing tables if they exist and create new ones
  auto setup = std::move(enable_fk.value())
                   .and_then(drop<Child> | if_exists)
                   .and_then(drop<Parent> | if_exists)
                   .and_then(begin_transaction)
                   .and_then(create_table<Parent>)
                   .and_then(create_table<Child>);

  if (!setup) {
    return false;
  }

  // Insert parent record
  Parent parent{.parent_id = parent_id, .name = "Test Parent"};
  auto insert_parent = std::move(setup.value()).and_then(insert(std::ref(parent)));

  if (!insert_parent) {
    return false;
  }

  // Insert child records with the same parent_id
  std::vector<Child> children = {
      Child{.child_id = 1, .parent_id = parent_id, .note = "Child 1"},
      Child{.child_id = 2, .parent_id = parent_id, .note = "Child 2"},
      Child{.child_id = 3, .parent_id = parent_id, .note = "Child 3"}
  };

  auto insert_children = std::move(insert_parent.value())
                             .and_then(insert(std::ref(children)))
                             .and_then(commit);

  if (!insert_children) {
    return false;
  }

  // Verify children exist before deletion
  auto count_before = std::move(insert_children.value())
                          .and_then(select(count<Child>())
                                        .from<Child>()
                                        .where("parent_id"_f == parent_id));

  if (!count_before || count_before.value().empty()) {
    return false;
  }

  int children_count_before = count_before.value().front();
  if (children_count_before != 3) {
    return false;
  }

  // Delete the parent record
  auto delete_parent = std::move(count_before.value())
                           .and_then(remove<Parent>()
                                         .where("parent_id"_f == parent_id));

  if (!delete_parent) {
    return false;
  }

  // Verify that child records were automatically deleted (cascade)
  auto count_after = std::move(delete_parent.value())
                         .and_then(select(count<Child>())
                                       .from<Child>()
                                       .where("parent_id"_f == parent_id));

  if (!count_after || count_after.value().empty()) {
    return false;
  }

  int children_count_after = count_after.value().front();

  // Cleanup
  std::move(count_after.value())
      .and_then(drop<Child> | if_exists)
      .and_then(drop<Parent> | if_exists);

  // Return true if cascade delete worked (children were deleted automatically)
  return children_count_after == 0;
}

}  // namespace cascade_delete_demo
```

This implementation:

1. **Connects to the SQLite database** "test_db.sqlite"
2. **Enables foreign key constraints** (required for SQLite to enforce CASCADE)
3. **Creates Parent and Child tables** with proper foreign key constraints
4. **Inserts a parent record** with the given parent_id
5. **Inserts multiple child records** referencing the parent
6. **Verifies children exist** before deletion (counts should be 3)
7. **Deletes the parent record**
8. **Verifies children were automatically deleted** due to CASCADE constraint
9. **Returns true** if cascade deletion worked (child count is 0 after parent deletion)

The foreign key constraint with CASCADE is automatically handled by the `ForeignKey` template in the `Child` struct definition.

