```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace column_is_null_checks {

struct Profile {
  sqlgen::PrimaryKey<int> profile_id;
  std::string display_name;
  std::optional<std::string> bio;
  std::optional<std::string> avatar_url;
};

struct Result {
  int profile_id;
  std::string display_name;
};

std::vector<Result> column_is_null_checks() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto db = sqlgen::sqlite::open("test_db.sqlite");

  // Query profiles where bio IS NULL OR avatar_url IS NULL
  auto profiles = db.exec(
      sqlgen::read<std::vector<Profile>> |
      where("bio"_c.is_null() or "avatar_url"_c.is_null())
  );

  // Transform Profile records to Result records
  std::vector<Result> results;
  results.reserve(profiles.size());

  for (const auto& profile : profiles) {
    results.push_back(Result{
      .profile_id = profile.profile_id.value,
      .display_name = profile.display_name
    });
  }

  return results;
}

}  // namespace column_is_null_checks
```

