#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace update_set_operations {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
  std::string status;
};

/**
 * description: update_set_operations.
 * sets the balance and status of an Account identified by acc_id.
 * @param acc_id: The id of Account to be updated.
 * @returns true if the update operations are successful, and false otherwise.
 */
bool update_set_operations(int acc_id) {
  // Connect to SQLite database
  auto conn_result = sqlgen::sqlite::Connection::make("test_db.sqlite");
  if (!conn_result) {
    return false;
  }
  auto conn = std::move(conn_result.value());

  // 1. Create Account table
  auto create_result = sqlgen::create_table<Account>(
      conn, sqlgen::if_not_exists());
  if (!create_result) {
    return false;
  }
  conn = std::move(create_result.value());

  // 2. Update balance and status using set(...)
  auto update_result = sqlgen::update<Account>(
      conn,
      sqlgen::set(sqlgen::field<"balance", Account> = 1000.0,
                  sqlgen::field<"status", Account> = std::string("active")),
      sqlgen::where(sqlgen::field<"account_id", Account> = acc_id));

  if (!update_result) {
    return false;
  }
  conn = std::move(update_result.value());

  // 3. Verify changes persisted
  auto read_result = sqlgen::read<Account>(
      conn,
      sqlgen::select_from<Account>(),
      sqlgen::where(sqlgen::field<"account_id", Account> = acc_id));

  if (!read_result) {
    return false;
  }

  auto [new_conn, accounts] = std::move(read_result.value());

  // Check if account exists and has correct values
  if (accounts.empty()) {
    return false;
  }

  const auto& account = accounts[0];
  if (account.balance != 1000.0 || account.status != "active") {
    return false;
  }

  return true;
}

}  // namespace update_set_operations
