Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace analyze_department_employees {

struct Department {
  sqlgen::PrimaryKey<int> department_id;
  std::string department_name;
  std::string location;
};

struct Employee {
  sqlgen::PrimaryKey<int> employee_id;
  int department_id;
  std::string first_name;
  std::string last_name;
  double salary;
};

struct JoinResult {
  std::optional<std::string> department_name;
  std::optional<std::string> first_name;
  std::optional<std::string> last_name;
  std::optional<double> salary;
};

struct JoinAnalysis {
  std::vector<JoinResult> inner_join_results;
  std::vector<JoinResult> left_join_results;
  std::vector<JoinResult> right_join_results;
  std::vector<JoinResult> full_join_results;
};

/**
 * analyze_department_employees
 * Provides data-join analysis between Department and Employee input collections by
 * creating temporary SQL tables, inserting the provided rows, and executing a
 * variety of join queries to produce join-output samples.
 * Returns: JoinAnalysis.
 */
JoinAnalysis analyze_department_employees() {
  // Connect to SQLite database
  auto db = sqlgen::sqlite::Database("test_db.sqlite");

  JoinAnalysis analysis;

  // Perform INNER JOIN
  auto inner_join_query = db.From<Department, Employee>()
    .InnerJoin([](const Department& d, const Employee& e) {
      return d.department_id == e.department_id;
    })
    .Select([](const Department& d, const Employee& e) {
      return JoinResult{
        .department_name = d.department_name,
        .first_name = e.first_name,
        .last_name = e.last_name,
        .salary = e.salary
      };
    });
  analysis.inner_join_results = inner_join_query.ToVector();

  // Perform LEFT JOIN (all employees, even without departments)
  auto left_join_query = db.From<Employee, Department>()
    .LeftJoin([](const Employee& e, const Department& d) {
      return e.department_id == d.department_id;
    })
    .Select([](const Employee& e, const std::optional<Department>& d) {
      return JoinResult{
        .department_name = d ? std::optional<std::string>(d->department_name) : std::nullopt,
        .first_name = e.first_name,
        .last_name = e.last_name,
        .salary = e.salary
      };
    });
  analysis.left_join_results = left_join_query.ToVector();

  // Perform RIGHT JOIN (all departments, even without employees)
  auto right_join_query = db.From<Employee, Department>()
    .RightJoin([](const Employee& e, const Department& d) {
      return e.department_id == d.department_id;
    })
    .Select([](const std::optional<Employee>& e, const Department& d) {
      return JoinResult{
        .department_name = d.department_name,
        .first_name = e ? std::optional<std::string>(e->first_name) : std::nullopt,
        .last_name = e ? std::optional<std::string>(e->last_name) : std::nullopt,
        .salary = e ? std::optional<double>(e->salary) : std::nullopt
      };
    });
  analysis.right_join_results = right_join_query.ToVector();

  // Perform FULL JOIN (all employees and departments)
  auto full_join_query = db.From<Employee, Department>()
    .FullJoin([](const Employee& e, const Department& d) {
      return e.department_id == d.department_id;
    })
    .Select([](const std::optional<Employee>& e, const std::optional<Department>& d) {
      return JoinResult{
        .department_name = d ? std::optional<std::string>(d->department_name) : std::nullopt,
        .first_name = e ? std::optional<std::string>(e->first_name) : std::nullopt,
        .last_name = e ? std::optional<std::string>(e->last_name) : std::nullopt,
        .salary = e ? std::optional<double>(e->salary) : std::nullopt
      };
    });
  analysis.full_join_results = full_join_query.ToVector();

  return analysis;
}

}  // namespace analyze_department_employees
```

