  sqlgen::PrimaryKey<int> id;
  std::string first_name;
  std::string last_name;
};

struct FullName {
  std::string full_name;
};

/**
 * This function queries the full names of all persons in the `Person` table.
 * Returns: std::vector<FullName>.
 */
inline std::vector<FullName> concat_function() {
    // Connect to the SQLite database
    auto conn = sqlgen::sqlite::Connection::connect("test_db.sqlite");

    if (!conn) {
        throw std::runtime_error("Failed to connect to database");
    }

    // Construct the query using CONCAT-like functionality
    // SQLite uses || operator for concatenation
    auto query = sqlgen::select(
        sqlgen::as<"full_name">(
            sqlgen::concat(
                sqlgen::field<"first_name", Person>(),
                sqlgen::lit(" "),
                sqlgen::field<"last_name", Person>()
            )
        )
    ).from<Person>();

    // Execute the query and collect results
    auto result = conn->select<FullName>(query);

    if (!result) {
        throw std::runtime_error("Query execution failed");
    }

    return *result;
}

}  // namespace concat_function
```

Note: Since SQLite doesn't have a native `CONCAT()` function like MySQL, it uses the `||` operator for string concatenation. The `sqlgen::concat()` function should handle this dialect difference automatically when transpiling to SQLite SQL. The query effectively generates SQL like:

```sql
SELECT first_name || ' ' || last_name AS full_name FROM Person
```

