    // Get the average price value
    double average_price = 0.0;
    for (const auto& row : avg_result) {
        average_price = row;
        break;  // Only one row with the average
    }

    // Return average price + 10 (to reach $10 profit per item)
    return average_price + 10.0;
}

}  // namespace aggregation_arithmetic
