#include <gtest/gtest.h>
#include "coalesce_function.hpp"
#include <algorithm>
#include <cctype>

namespace coalesce_function {
TEST(coalesce_function, test_query_generation) {
    using namespace std;
    using namespace sqlgen;
    using namespace sqlgen::literals;
    vector<Profile> profiles = vector<Profile>{
        {1, "Bob"},
        {2, nullopt},
        {3, "Alice"}
    };
    auto conn = sqlite::connect("test_db.sqlite").value();
    drop<Profile>(conn);
    create_table<Profile>(conn);
    insert(conn, profiles);

    vector<NicknameResult> query_result = coalesce_function();
    EXPECT_EQ(query_result.size(), 3);
    EXPECT_EQ(query_result[0].display_name, "Bob");
    EXPECT_EQ(query_result[1].display_name, "Anonymous");
}
}

related functions.definition:
template <class... Ts>
auto coalesce(const Ts&... _ts) {
  static_assert(sizeof...(_ts) > 1,
                "coalesce(...) must have at least two inputs.");
  using Type = rfl::Tuple<typename transpilation::ToTranspilationType<
      std::remove_cvref_t<Ts>>::Type...>;
  return transpilation::Operation<transpilation::Operator::coalesce, Type>{
      .operand1 = Type(transpilation::to_transpilation_type(_ts)...)};
}

template <rfl::internal::StringLiteral _alias, class QueryType,
          class... FieldTypes>
inline auto select_from(const QueryType& _query, const FieldTypes&... _fields) {
  using FieldsType =
      rfl::Tuple<typename internal::GetColType<FieldTypes>::Type...>;
  return SelectFrom<QueryType, Literal<_alias>, FieldsType>{
      .fields_ =
          FieldsType(internal::GetColType<FieldTypes>::get_value(_fields)...),
      .from_ = _query};
}

