```cpp
#pragma once

#include <algorithm>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace get_top_products {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string product_name;
  std::string category;
  double price;
};

struct Sales {
  sqlgen::PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  sqlgen::Date sale_date;
};

struct TopProduct {
  int product_id;
  std::string product_name;
  std::string category;
  double total_sales;
};

/**
 * Description: This function retrieves the top products based on total sales.
 * @param limit_count The number of top products to retrieve. Default is 10.
 * Returns: std::vector<TopProduct>.
 */
std::vector<TopProduct> get_top_products(size_t limit_count = 10) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite").value();

  // Build the query using sqlgen
  // SELECT p.product_id, p.product_name, p.category, SUM(p.price * s.quantity) as total_sales
  // FROM Product p
  // INNER JOIN Sales s ON p.product_id = s.product_id
  // GROUP BY p.product_id, p.product_name, p.category
  // ORDER BY total_sales DESC
  // LIMIT limit_count

  auto query = select_from<Product>()
    .with_fields(
      "product_id"_c,
      "product_name"_c,
      "category"_c,
      sum("price"_c * col<Sales>("quantity")) | as("total_sales")
    )
    .inner_join<Sales>(col<Product>("product_id") == col<Sales>("product_id"))
    .group_by(
      col<Product>("product_id"),
      col<Product>("product_name"),
      col<Product>("category")
    )
    .order_by(desc("total_sales"_c))
    .limit(limit_count);

  // Execute the query and retrieve results
  auto result = conn.execute<std::vector<TopProduct>>(query);

  if (result) {
    return result.value();
  }

  // Return empty vector if query fails
  return std::vector<TopProduct>();
}

}  // namespace get_top_products
```

This implementation:

1. **Connects to the database** using `sqlite::connect("test_db.sqlite")`
2. **Builds the query** using sqlgen's fluent API:
   - Uses `select_from<Product>()` to start the query
   - Specifies fields including the calculated `SUM(price * quantity)` as `total_sales`
   - Performs an `inner_join` with the Sales table on matching product_id
   - Groups by product_id, product_name, and category
   - Orders by total_sales in descending order
   - Applies the limit
3. **Executes the query** and maps results to `std::vector<TopProduct>`
4. **Returns the results** or an empty vector if the query fails

