```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace create_view_order_summary {

struct Order {
  static constexpr const char* tablename = "Order";
  sqlgen::PrimaryKey<int> order_id;
  std::string customer;
};

struct OrderItem {
  static constexpr const char* tablename = "OrderItem";
  sqlgen::PrimaryKey<int> item_id;
  int order_id;
  double unit_price;
  int quantity;
};

struct OrderSummary {
  static constexpr const char* tablename = "OrderSummaryView";
  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> order_id;
  std::string customer;
  double total;
};

/**
 * Description: Create a view `OrderSummaryView` that shows order ID, customer name, and (unit_price * quantity) as total price for each order.
 * Returns: std::vector<OrderSummary>.
 */
std::vector<OrderSummary> create_view_order_summary() {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Step 1: Connect to the SQLite database
    auto conn_result = sqlite::connect("test_db.sqlite");
    if (!conn_result) {
        return {};
    }
    auto conn = *conn_result;

    // Step 2: Create the query for the view
    // SELECT o.order_id, o.customer, SUM(oi.unit_price*oi.quantity) as total
    // FROM Order o INNER JOIN OrderItem oi ON o.order_id=oi.order_id
    // GROUP BY o.order_id, o.customer
    auto order_summary_query = 
        select_from<Order>("order_id"_c, "customer"_c)
        .inner_join<OrderItem>(on("order_id"_c))
        .select(sum("unit_price"_c * "quantity"_c).as("total"))
        .group_by("order_id"_c, "customer"_c);

    // Step 3: Create the view using CREATE VIEW AS
    auto create_view_stmt = create_as<OrderSummary>(order_summary_query) | if_not_exists;

    // Step 4: Execute the create view statement
    auto create_result = conn->execute(create_view_stmt);
    if (!create_result) {
        return {};
    }

    // Step 5: Read data from the view
    auto read_result = conn->read<OrderSummary>();
    if (!read_result) {
        return {};
    }

    // Step 6: Return the records as a vector
    return *read_result;
}

}  // namespace create_view_order_summary
```

