Based on the code fragments provided, I can see how the `sqlgen` library works with SQLite databases, aggregations, and group by operations. Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace group_by_with_aggregations {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string name;
};

struct Post {
  sqlgen::PrimaryKey<int> post_id;
  int user_id;
  std::string content;
};

struct Stats {
  sqlgen::PrimaryKey<int> user_id;
  std::string name;
  int post_count;
  std::optional<double> avg_length;
};

/**
 * Description: This function retrieves user statistics including post count and average post length.
 * Returns: std::vector<Stats>.
 */
std::vector<Stats> group_by_with_aggregations() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto connection = sqlite::connect("test_db.sqlite");

  if (!connection) {
    return {};
  }

  // Build query to join User and Post tables, group by user, and compute aggregations
  auto query = select_from<User>(
      "User.user_id"_c.as<"user_id">(),
      "User.name"_c.as<"name">(),
      count().as<"post_count">(),
      avg(length("Post.content"_c)).as<"avg_length">()
  ) 
  | join<Post>(on("User.user_id"_c == "Post.user_id"_c))
  | group_by("User.user_id"_c, "User.name"_c)
  | to<Stats>;

  // Execute query and return results
  auto result = connection.and_then(query);

  if (result) {
    return result.value();
  }

  return {};
}

}  // namespace group_by_with_aggregations
```

This implementation:

1. **Connects to the SQLite database** "test_db.sqlite" using `sqlite::connect()`
2. **Joins User and Post tables** on the `user_id` foreign key
3. **Groups by user** using `group_by()` with `user_id` and `name`
4. **Computes aggregations**:
   - `count()` for the number of posts per user as `post_count`
   - `avg(length("Post.content"_c))` for the average content length as `avg_length`
5. **Returns the results** as a vector of `Stats` structs using the `to<Stats>` converter

The query follows the pattern seen in the test files, using the fluent API with pipe operators to chain operations together.

