#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>

namespace create_table_as_select {

struct Source {
  sqlgen::PrimaryKey<int> id;
  int value;
};

struct Target {
  int value;
};

/**
 * Description: This function creates a table `Target` from a select query on `Source` 
 * Returns: std::vector<Target>.
 */
inline std::vector<Target> create_table_as_select() {
    // Connect to the SQLite database
    auto conn = sqlgen::sqlite::connect("test_db.sqlite").value();

    // Create the CREATE TABLE AS SELECT statement
    // Select from Source where value > 100
    auto select_query = sqlgen::select_from<Source>()
                            .where(sqlgen::field<"value", Source>() > 100);

    // Create table Target from the select query
    auto create_stmt = sqlgen::create_as<Target>(select_query);

    // Execute the CREATE TABLE AS SELECT statement
    conn->execute(create_stmt);

    // Now read all records from the newly created Target table
    auto read_query = sqlgen::select_from<Target>();

    // Execute the select query and return the results
    auto result = conn->read<Target>(read_query);

    if (result) {
